const initialCalendarDate=new Date();
function loadUiState(){try{return JSON.parse(sessionStorage.getItem('proelium-ui-state'))||{}}catch{return {}}}
const savedUiState=loadUiState();
const validViews=new Set([...navItems.map(item=>item[0]),'clientDetail','quoteDetail']);
const state = { view:validViews.has(savedUiState.view)?savedUiState.view:'dashboard', query:'', selectedClient:savedUiState.selectedClient||null, selectedQuote:savedUiState.selectedQuote||null, biDimension:'client', biMarketFilter:'all', biMarketSort:'performance', biMarketAsset:null, agendaYear:Number.isInteger(savedUiState.agendaYear)?savedUiState.agendaYear:initialCalendarDate.getFullYear(), agendaMonth:Number.isInteger(savedUiState.agendaMonth)?savedUiState.agendaMonth:initialCalendarDate.getMonth(), agendaSelectedDate:null, data:loadData(), revision:0, updatedAt:null, syncing:false };
