function knowledge(){const cards=state.data.articles.filter(a=>matches(a.title,a.tag,a.summary)).map(a=>`<article class="card article"><span class="tag">${a.tag}</span><h3>${a.title}</h3><p>${a.summary}</p><button class="button secondary">Abrir artigo</button></article>`).join('');return heading('Base de conhecimento','Procedimentos, manuais e soluções reutilizáveis.')+`<div class="knowledge-grid">${cards||'<div class="empty">Nenhum artigo encontrado.</div>'}</div>`}
const views={dashboard,clients,clientDetail,projects,processes,tasks,agenda,commercial,quoteDetail,products,installations,operations,finance,bi,biMarket:biMarketV2,quality,equipment,knowledge};

function render(){renderNav();$('#pageTitle').textContent=state.view==='clientDetail'?'Cliente 360°':state.view==='quoteDetail'?'Análise do orçamento':navItems.find(n=>n[0]===state.view)[2];$('#content').innerHTML=views[state.view]();if(state.view==='clientDetail')addDeleteControl();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>openClient(b.dataset.client));document.querySelectorAll('[data-quote]').forEach(b=>b.onclick=()=>openQuote(b.dataset.quote));document.querySelectorAll('[data-edit-client]').forEach(b=>b.onclick=()=>openForm('client',b.dataset.editClient));document.querySelectorAll('[data-delete-product]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.deleteProduct));document.querySelectorAll('[data-advance-opportunity]').forEach(b=>b.onclick=()=>advanceOpportunity(b.dataset.advanceOpportunity));document.querySelectorAll('[data-convert-opportunity]').forEach(b=>b.onclick=()=>convertOpportunity(b.dataset.convertOpportunity));document.querySelectorAll('[data-agenda-day]').forEach(day=>day.onclick=()=>openAgendaQuick(day.dataset.agendaDay));document.querySelectorAll('[data-add-appointment-date]').forEach(b=>b.onclick=()=>openForm('appointment','',{date:b.dataset.addAppointmentDate}));document.querySelectorAll('[data-agenda-month]').forEach(b=>b.onclick=()=>{state.agendaMonth+=b.dataset.agendaMonth==='next'?1:-1;if(state.agendaMonth>11){state.agendaMonth=0;state.agendaYear++}if(state.agendaMonth<0){state.agendaMonth=11;state.agendaYear--}state.agendaSelectedDate=null;render()});const dim=$('#biDimension');if(dim)dim.onchange=e=>{state.biDimension=e.target.value;render()};document.querySelectorAll('[data-market-filter]').forEach(b=>b.onclick=()=>{state.biMarketFilter=b.dataset.marketFilter;render()});const marketSort=$('#marketSort');if(marketSort)marketSort.onchange=e=>{state.biMarketSort=e.target.value;render()};rememberUiState()}
function setMenu(open){$('#sidebar').classList.toggle('open',open);$('#menuBackdrop').classList.toggle('visible',open)}
function go(view){state.view=view;state.query='';$('#globalSearch').value='';setMenu(false);render()}
function openClient(id){state.selectedClient=id;state.view='clientDetail';render()}
function openQuote(id){state.selectedQuote=id;state.view='quoteDetail';render()}
function addDeleteControl(){const actions=document.querySelector('.client-hero .hero-actions');if(!actions)return;const button=document.createElement('button');button.className='button danger-outline';button.textContent='Excluir cliente';button.onclick=()=>deleteClient(state.selectedClient);actions.prepend(button)}
function deleteClient(id){const client=state.data.clients.find(c=>c.id===id);if(!client)return;const projectIds=state.data.projects.filter(p=>p.clientId===id).map(p=>p.id),quoteIds=state.data.quotes.filter(q=>q.clientId===id).map(q=>q.id);if(!confirm(`Excluir ${client.name}?\n\nTambém serão removidos os projetos, tarefas, orçamentos, instalações e todo o histórico vinculados. Esta ação não pode ser desfeita.`))return;state.data.tasks=state.data.tasks.filter(t=>!projectIds.includes(t.projectId));state.data.installations=state.data.installations.filter(i=>i.clientId!==id);state.data.activities=state.data.activities.filter(a=>a.clientId!==id);state.data.projects=state.data.projects.filter(p=>p.clientId!==id);state.data.quoteRooms=state.data.quoteRooms.filter(r=>!quoteIds.includes(r.quoteId));state.data.quotes=state.data.quotes.filter(q=>q.clientId!==id);state.data.clients=state.data.clients.filter(c=>c.id!==id);state.selectedClient=null;state.view='clients';persist();render();toast('Cliente e registros vinculados foram excluídos.')}
function deleteProduct(id){const product=productById(id);if(!product)return;const uses=state.data.quoteRooms.reduce((n,r)=>n+r.items.filter(i=>i.productId===id).length,0);const detail=uses?`\n\nEste produto aparece em ${uses} ambiente(s) de orçamento e também será removido desses ambientes.`:'';if(!confirm(`Excluir ${product.name}?${detail}\n\nEsta ação não pode ser desfeita.`))return;state.data.products=state.data.products.filter(p=>p.id!==id);state.data.quoteRooms.forEach(r=>r.items=r.items.filter(i=>i.productId!==id));persist();render();toast('Produto excluído do catálogo.')}
function advanceOpportunity(id){const opportunity=state.data.opportunities.find(o=>o.id===id);if(!opportunity)return;const stages=['Novo contato','Qualificação','Visita','Orçamento'];const index=stages.indexOf(opportunity.stage);opportunity.stage=stages[Math.min(index+1,stages.length-1)];persist();render();toast(`Oportunidade movida para ${opportunity.stage}.`)}
function convertOpportunity(id){const opportunity=state.data.opportunities.find(o=>o.id===id);if(!opportunity)return;const existing=state.data.clients.find(c=>c.name.toLowerCase()===opportunity.company.toLowerCase());if(!existing){state.data.clients.push({id:uid('cli'),name:opportunity.company,document:'',contact:opportunity.contact,email:opportunity.email,phone:opportunity.phone,address:'',city:'',notes:`Origem: oportunidade comercial (${opportunity.source}).`,status:'Potencial'})}opportunity.stage='Ganho';opportunity.lossReason='';persist();render();toast(existing?'Oportunidade marcada como ganha.':'Cliente criado a partir da oportunidade.')}

const forms={
  client:{title:'Cliente',fields:[['name','Nome / razão social','text'],['document','CNPJ / CPF','text'],['contact','Contato principal','text'],['email','E-mail','email'],['phone','Telefone','tel'],['city','Cidade','text'],['address','Endereço completo','text'],['status','Status','clientStatus'],['notes','Observações','textarea']]},
  opportunity:{title:'Nova oportunidade',fields:[['company','Empresa / pessoa','text'],['contact','Contato','text'],['phone','Telefone','tel'],['email','E-mail','email'],['source','Origem do contato','text'],['owner','Responsável pelo atendimento','text'],['stage','Etapa atual','opportunityStage'],['nextAction','Próxima ação','text'],['nextDue','Prazo da próxima ação','text'],['estimatedValue','Valor estimado (R$)','number'],['lossReason','Motivo de perda (se perdido)','text']]},
  project:{title:'Novo projeto',fields:[['name','Nome do projeto','text'],['code','Código','text'],['clientId','Cliente','clients'],['manager','Responsável','text'],['technicalStage','Etapa técnica','technicalStage'],['budget','Valor aprovado (R$)','number'],['due','Prazo','text']]},
  task:{title:'Nova tarefa',fields:[['title','Título','text'],['projectId','Projeto','projects'],['assignee','Responsável','text'],['priority','Prioridade','priority'],['due','Data','date'],['time','Horário','time']]},
  appointment:{title:'Novo compromisso',fields:[['title','Compromisso','text'],['assignee','Responsável','text'],['date','Data','date'],['time','Horário','time'],['note','Observação','textarea']]},
  installation:{title:'Nova instalação',fields:[['clientId','Cliente','clients'],['projectId','Projeto','projects'],['type','Tipo da instalação','text'],['site','Local / unidade','text'],['lead','Responsável técnico','text'],['due','Prazo','text']]},
  activity:{title:'Registrar no histórico',fields:[['clientId','Cliente','clients'],['type','Tipo do registro','activityType'],['title','Assunto','text'],['note','Descrição completa','textarea']]}
  ,product:{title:'Novo produto ou serviço',fields:[['sku','Código / SKU','text'],['name','Nome do item','text'],['brand','Marca / linha','text'],['category','Categoria','text'],['mode','Modalidade','productMode'],['unit','Unidade','unit'],['cost','Custo unitário (R$)','number'],['price','Preço de venda (R$)','number']]}
  ,room:{title:'Novo cômodo / ambiente',fields:[['name','Nome do cômodo ou ambiente','text']]}
  ,quoteItem:{title:'Adicionar item ao ambiente',fields:[['roomId','Cômodo / ambiente','rooms'],['productId','Produto ou serviço','products'],['qty','Quantidade','number']]}
  ,evaluation:{title:'Avaliação de qualidade e compromisso',fields:[['projectId','Projeto avaliado','projects'],['source','Fonte: Interna ou Cliente','text'],['evaluator','Nome de quem avaliou','text'],['installation','Qualidade da instalação (1 a 5)','number'],['service','Qualidade do atendimento (1 a 5)','number'],['commitment','Compromisso e execução (1 a 5)','number'],['deadline','Cumprimento de prazo (1 a 5)','number'],['note','Evidência, comentário ou melhoria','textarea']]}
};
function todayInput(){const now=new Date(),month=String(now.getMonth()+1).padStart(2,'0'),day=String(now.getDate()).padStart(2,'0');return `${now.getFullYear()}-${month}-${day}`}
function findRecord(kind,id){const collections={client:'clients',appointment:'appointments',task:'tasks',installation:'installations',opportunity:'opportunities'};return collections[kind]?state.data[collections[kind]].find(item=>item.id===id):null}
function openForm(kind,editId='',prefill={}){const def=forms[kind],current=editId?findRecord(kind,editId):null;$('#dialogTitle').textContent=current?`Editar ${kind==='opportunity'?'oportunidade':kind==='installation'?'instalação':kind==='task'?'tarefa':kind==='appointment'?'compromisso':'cadastro'}`:def.title;$('#recordForm').dataset.kind=kind;$('#recordForm').dataset.editId=editId;$('#saveButton').textContent=current?'Salvar ajuste':'Salvar registro';$('#formFields').innerHTML=def.fields.map(([name,label,type])=>{let input;const value=prefill[name]??current?.[name]??(state.selectedClient&&name==='clientId'?state.selectedClient:type==='date'?todayInput():'');const options=(values)=>values.map(v=>`<option value="${v}" ${v===value?'selected':''}>${v}</option>`).join('');if(type==='clients')input=`<select name="${name}" required>${state.data.clients.map(c=>`<option value="${c.id}" ${c.id===value?'selected':''}>${c.name}</option>`)}</select>`;else if(type==='projects')input=`<select name="${name}" required>${state.data.projects.map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${p.name}</option>`)}</select>`;else if(type==='products')input=`<select name="${name}" required>${state.data.products.map(p=>`<option value="${p.id}">${p.name} · ${money(p.price)}</option>`)}</select>`;else if(type==='rooms'){const rooms=state.data.quoteRooms.filter(r=>r.quoteId===state.selectedQuote);input=`<select name="${name}" required>${rooms.map(r=>`<option value="${r.id}">${r.name}</option>`)}</select>`}else if(type==='priority')input=`<select name="${name}">${options(['Média','Alta','Urgente','Baixa'])}</select>`;else if(type==='technicalStage')input=`<select name="${name}">${options(['Projeto técnico','Cabeamento','Instalação'])}</select>`;else if(type==='opportunityStage')input=`<select name="${name}">${options(['Novo contato','Qualificação','Visita','Orçamento','Ganho','Perdido'])}</select>`;else if(type==='clientStatus')input=`<select name="${name}">${options(['Ativo','Potencial','Inativo'])}</select>`;else if(type==='productMode')input=`<select name="${name}">${options(['Venda','Disponibilização','Venda ou disponibilização','Serviço'])}</select>`;else if(type==='unit')input=`<select name="${name}">${options(['un','m','h','kit','mês'])}</select>`;else if(type==='activityType')input=`<select name="${name}">${options(['Contato','Visita técnica','Proposta','Pendência','Manutenção'])}</select>`;else if(type==='textarea')input=`<textarea name="${name}" required>${value}</textarea>`;else input=`<input name="${name}" type="${type}" value="${value}" min="${type==='number'?'0':''}" step="${type==='number'?'0.01':''}" required>`;return `<div class="field ${type==='textarea'||name==='address'?'full':''}"><label>${label}</label>${input}</div>`}).join('');$('#recordDialog').showModal()}
function saveRecord(kind,data,editId=''){if(kind==='client'){if(editId){const index=state.data.clients.findIndex(c=>c.id===editId);state.data.clients[index]={...state.data.clients[index],...data}}else state.data.clients.push({id:uid('cli'),...data})}if(kind==='opportunity')state.data.opportunities.unshift({id:uid('opp'),company:data.company,contact:data.contact,phone:data.phone,email:data.email,source:data.source,owner:data.owner,stage:data.stage,nextAction:data.nextAction,nextDue:data.nextDue,estimatedValue:Number(data.estimatedValue||0),lossReason:data.lossReason});if(kind==='project')state.data.projects.push({id:uid('prj'),name:data.name,code:data.code,clientId:data.clientId,manager:data.manager,technicalStage:data.technicalStage,budget:Number(data.budget||0),cost:0,status:'Planejamento',progress:0,due:data.due});if(kind==='task')state.data.tasks.push({id:uid('tsk'),title:data.title,projectId:data.projectId,assignee:data.assignee,priority:data.priority,status:'Aberta',due:data.due,time:data.time});if(kind==='appointment'){const appointment={title:data.title,assignee:data.assignee,date:data.date,time:data.time,note:data.note};if(editId){const index=state.data.appointments.findIndex(a=>a.id===editId);if(index>=0)state.data.appointments[index]={...state.data.appointments[index],...appointment}}else state.data.appointments.unshift({id:uid('apt'),...appointment})}if(kind==='installation')state.data.installations.push({id:uid('ins'),clientId:data.clientId,projectId:data.projectId,type:data.type,site:data.site,lead:data.lead,stage:'Projeto técnico',progress:0,due:data.due,status:'Planejamento'});if(kind==='activity')state.data.activities.unshift({id:uid('act'),clientId:data.clientId,type:data.type,title:data.title,note:data.note,date:'Agora'});if(kind==='product')state.data.products.push({id:uid('prd'),sku:data.sku,name:data.name,brand:data.brand,category:data.category,mode:data.mode,unit:data.unit,cost:Number(data.cost),price:Number(data.price),active:true});if(kind==='room')state.data.quoteRooms.push({id:uid('amb'),quoteId:state.selectedQuote,name:data.name,items:[]});if(kind==='quoteItem'){const room=state.data.quoteRooms.find(r=>r.id===data.roomId);const existing=room?.items.find(i=>i.productId===data.productId);if(existing)existing.qty+=Number(data.qty);else room?.items.push({productId:data.productId,qty:Number(data.qty)})}persist();render();toast(editId?'Ajuste salvo com sucesso.':'Registro salvo com sucesso.')}
function saveEditedRecord(kind,data,id){const collections={client:'clients',appointment:'appointments',task:'tasks',installation:'installations',opportunity:'opportunities'};const list=state.data[collections[kind]],index=list?.findIndex(item=>item.id===id);if(index===undefined||index<0)return;const patch={...data};if(kind==='opportunity')patch.estimatedValue=Number(data.estimatedValue||0);list[index]={...list[index],...patch};persist();render();toast('Ajuste salvo com sucesso.')}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)}
const seasons=[['summer','☀ Verão'],['autumn','◒ Outono'],['winter','❄ Inverno'],['spring','✿ Primavera']];
function currentSeason(){const month=new Date().getMonth()+1;return month<=2||month===12?'summer':month<=5?'autumn':month<=8?'winter':'spring'}
function applySeason(name){const season=seasons.find(([id])=>id===name)||seasons.find(([id])=>id===currentSeason());document.documentElement.dataset.season=season[0];$('#seasonButton').textContent=season[1];localStorage.setItem('proelium-season',season[0])}
function setupHeader(){const date=new Intl.DateTimeFormat('pt-BR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(new Date()).replace(/\.$/,'');$('#headerDate').textContent=date;applySeason(localStorage.getItem('proelium-season')||currentSeason());$('#seasonButton').onclick=()=>{const active=seasons.findIndex(([id])=>id===document.documentElement.dataset.season);const next=seasons[(active+1)%seasons.length];applySeason(next[0]);toast(`Tema ${next[1]} aplicado.`)}}
const readingScales=[100,115,130];
function applyAccessibility(){const scale=Number(localStorage.getItem('proelium-font-scale')||100),contrast=localStorage.getItem('proelium-high-contrast')==='true';document.body.dataset.fontScale=scale;document.body.classList.toggle('high-contrast',contrast);$('#fontValue').textContent=`${scale}%`;$('#fontDown').disabled=scale===readingScales[0];$('#fontUp').disabled=scale===readingScales[readingScales.length-1];$('#contrastButton').textContent=contrast?'Desativar alto contraste':'Ativar alto contraste';$('#contrastButton').setAttribute('aria-pressed',contrast)}
function setupAccessibility(){applyAccessibility();$('#accessibilityButton').onclick=()=>$('#accessibilityDialog').showModal();$('#accessibilityClose').onclick=()=>$('#accessibilityDialog').close();$('#fontDown').onclick=()=>{const current=Number(localStorage.getItem('proelium-font-scale')||100),index=readingScales.indexOf(current);localStorage.setItem('proelium-font-scale',readingScales[Math.max(0,index-1)]);applyAccessibility()};$('#fontUp').onclick=()=>{const current=Number(localStorage.getItem('proelium-font-scale')||100),index=readingScales.indexOf(current);localStorage.setItem('proelium-font-scale',readingScales[Math.min(readingScales.length-1,index+1)]);applyAccessibility()};$('#contrastButton').onclick=()=>{localStorage.setItem('proelium-high-contrast',String(!document.body.classList.contains('high-contrast')));applyAccessibility()}}

$('#navigation').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view)});
$('#globalSearch').addEventListener('input',e=>{state.query=e.target.value;render()});
$('#menuButton').onclick=()=>setMenu(!$('#sidebar').classList.contains('open'));
$('#menuBackdrop').onclick=()=>setMenu(false);
$('#agendaQuickClose').onclick=()=>$('#agendaQuickDialog').close();
$('#agendaItemClose').onclick=()=>$('#agendaItemDialog').close();
function closeRecordDialog(){const form=$('#recordForm');$('#recordDialog').close();form.reset();form.dataset.editId='';$('#saveButton').textContent='Salvar registro'}
$('#recordCloseX').onclick=closeRecordDialog;
$('#recordCancel').onclick=closeRecordDialog;
$('#recordForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget)),kind=e.currentTarget.dataset.kind,editId=e.currentTarget.dataset.editId;if(kind==='evaluation'){const scores=['installation','service','commitment','deadline'].map(key=>Number(data[key]));if(scores.some(score=>score<1||score>5)){toast('As quatro notas devem estar entre 1 e 5.');return}state.data.evaluations.unshift({id:uid('eva'),...data,installation:Number(data.installation),service:Number(data.service),commitment:Number(data.commitment),deadline:Number(data.deadline),date:todayInput()});persist();render();toast('Avaliação registrada com sucesso.')}else if(editId&&findRecord(kind,editId))saveEditedRecord(kind,data,editId);else saveRecord(kind,data,editId);closeRecordDialog()});
function addBackGuard(){history.pushState({proeliumApp:true},'',location.href)}
function handleBack(){addBackGuard();if($('#sidebar').classList.contains('open')){setMenu(false);return}if(state.view!=='dashboard'){go('dashboard');toast('Você voltou para a Visão geral.');return}toast('Você já está na Visão geral.')}
if(location.protocol!=='file:'){addBackGuard();window.addEventListener('popstate',handleBack);window.addEventListener('pageshow',()=>addBackGuard())}
setupHeader();
setupAccessibility();
render();
connectSharedData();
document.addEventListener('click',event=>{const asset=event.target.closest('[data-market-asset]'),close=event.target.closest('[data-market-close]');if(asset){state.biMarketAsset=asset.dataset.marketAsset;render()}if(close){state.biMarketAsset=null;render()}});
const splash=$('#splash');let splashTimer;
function hideSplash(delay=2300){clearTimeout(splashTimer);splashTimer=setTimeout(()=>splash?.classList.add('hide'),delay)}
if(splash)hideSplash();
